"""Patches the android/ folder generated by `flutter create`.

Safe to run more than once. It
  * adds the INTERNET permission (the preview server needs a local socket),
  * allows cleartext HTTP to 127.0.0.1/localhost only,
  * sets the app name to "Decode",
  * installs the Decode launcher icons.
"""
import pathlib
import re
import shutil
import sys

main = pathlib.Path("android/app/src/main")
manifest = main / "AndroidManifest.xml"
if not manifest.exists():
    sys.exit("android/ not found - run `flutter create` first")

text = manifest.read_text(encoding="utf-8")

if "android.permission.INTERNET" not in text:
    text = text.replace(
        "<application",
        '<uses-permission android:name="android.permission.INTERNET"/>\n    <application',
        1,
    )

if "networkSecurityConfig" not in text:
    text = text.replace(
        "<application",
        '<application\n        android:networkSecurityConfig="@xml/network_security_config"',
        1,
    )

text = re.sub(r'android:label="[^"]*"', 'android:label="Decode"', text, count=1)
manifest.write_text(text, encoding="utf-8")

xml_dir = main / "res" / "xml"
xml_dir.mkdir(parents=True, exist_ok=True)
(xml_dir / "network_security_config.xml").write_text(
    """<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">127.0.0.1</domain>
        <domain includeSubdomains="false">localhost</domain>
    </domain-config>
</network-security-config>
""",
    encoding="utf-8",
)

icons = pathlib.Path("tool/android_icons")
for folder in icons.iterdir():
    if folder.is_dir():
        target = main / "res" / folder.name
        target.mkdir(parents=True, exist_ok=True)
        shutil.copy(folder / "ic_launcher.png", target / "ic_launcher.png")

print("Android project patched")
